contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log) public payable {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool setLogFileReverted;
        c.SetLogFile(log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setLogFileReverted = true;
        } else {
            setLogFileReverted = false;
        }

        bool initializedReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            initializedReverted = true;
        } else {
            initializedReverted = false;
        }

        assert(!setLogFileReverted && !initializedReverted && c.MinSum() == beforeMinSum);
    }

    receive() external payable {}
}

